81	void QueryNormalizer::visit(ASTIdentifier & node, ASTPtr & ast, Data & data)
82	{
83	    /// We do handle cycles via tracking current_asts
84	    /// but in case of bug in that tricky logic we need to prevent stack overflow
85	    checkStackSize();
86	
87	    auto & current_asts = data.current_asts;
88	    String & current_alias = data.current_alias;
89	
90	    if (!IdentifierSemantic::getColumnName(node))
91	        return;
92	
93	    if (data.settings.prefer_column_name_to_alias)
94	    {
95	        if (data.source_columns_set.contains(node.name()))
96	            return;
97	    }
98	
99	    /// If it is an alias, but not a parent alias (for constructs like "SELECT column + 1 AS column").
100	    if (!data.allow_self_aliases && current_alias == node.name())
101	        throw Exception(ErrorCodes::CYCLIC_ALIASES, "Self referencing of {} to {}. Cyclic alias",
102	                        backQuote(current_alias), backQuote(node.name()));
103	    auto it_alias = data.aliases.find(node.name());
104	
105	    if (it_alias != data.aliases.end() && current_alias != node.name())
106	    {
107	        if (!IdentifierSemantic::canBeAlias(node))
108	            return;
109	
110	        /// We are alias for other column (node.name), but we are alias by
111	        /// ourselves to some other column
112	        const auto & alias_node = it_alias->second;
113	
114	        String our_alias_or_name = alias_node->getAliasOrColumnName();
115	        std::optional<String> our_name = IdentifierSemantic::getColumnName(alias_node);
116	
117	        String node_alias = ast->tryGetAlias();
118	
119	        if (current_asts.contains(alias_node.get()) /// We have loop of multiple aliases
120	            || (node.name() == our_alias_or_name && our_name && node_alias == *our_name)) /// Our alias points to node.name, direct loop
121	            throw Exception(ErrorCodes::CYCLIC_ALIASES, "Cyclic aliases");
122	
123	        /// Let's replace it with the corresponding tree node.
124	        if (!node_alias.empty() && node_alias != our_alias_or_name)
125	        {
126	            /// Avoid infinite recursion here
127	            auto opt_name = IdentifierSemantic::getColumnName(alias_node);
128	            bool is_cycle = opt_name && *opt_name == node.name();
129	
130	            if (!is_cycle)
131	            {
132	                /// In a construct like "a AS b", where a is an alias, you must set alias b to the result of substituting alias a.
133	                /// Check size of the alias before cloning too large alias AST
134	                alias_node->checkSize(data.settings.max_expanded_ast_elements);
135	                ast = alias_node->clone();
136	                ast->setAlias(node_alias);
137	
138	                /// If the cloned AST was finished, this one should also be considered finished
139	                if (data.finished_asts.contains(alias_node))
140	                    data.finished_asts[ast] = ast;
141	
142	                /// If we had an alias for node_alias, point it instead to the new node so we don't have to revisit it
143	                /// on subsequent calls
144	                if (auto existing_alias = data.aliases.find(node_alias); existing_alias != data.aliases.end())
145	                    existing_alias->second = ast;
146	            }
147	        }
148	        else
149	        {
150	            /// Check size of the alias before cloning too large alias AST
151	            alias_node->checkSize(data.settings.max_expanded_ast_elements);
152	            auto alias_name = ast->getAliasOrColumnName();
153	            ast = alias_node->clone();
154	            ast->setAlias(alias_name);
155	
156	            /// If the cloned AST was finished, this one should also be considered finished
157	            if (data.finished_asts.contains(alias_node))
158	                data.finished_asts[ast] = ast;
159	
160	            /// If we had an alias for node_alias, point it instead to the new node so we don't have to revisit it
161	            /// on subsequent calls
162	            if (auto existing_alias = data.aliases.find(node_alias); existing_alias != data.aliases.end())
163	                existing_alias->second = ast;
164	        }
165	    }
